const DAY_IN_MILLISECONDS = 24 * 60 * 60 * 1000
const dateFormatterCache = new Map()

export function signedDifferenceInDays(fromDate, toDate) {
  return Math.round((beginningOfDay(toDate) - beginningOfDay(fromDate)) / DAY_IN_MILLISECONDS)
}

export function beginningOfDay(date) {
  return new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()))
}

export function formatLocalTime(timestamp, format = "relative", now = new Date()) {
  const date = timestamp instanceof Date ? timestamp : new Date(timestamp)

  if (Number.isNaN(date.getTime())) return String(timestamp ?? "")

  switch (format) {
    case "time":
      return formatDate(date, { hour: "numeric", minute: "2-digit" })
    case "date":
      return formatLocalDate(date, now)
    case "date-with-year":
      return formatDate(date, { month: "short", day: "2-digit", year: "numeric" })
    case "weekday-date":
      return formatDate(date, { weekday: "long", month: "long", day: "numeric" })
    case "date-time":
      return formatDate(date, { month: "numeric", day: "numeric", year: "2-digit", hour: "numeric", minute: "2-digit" })
    case "date-time-with-year":
      return formatDate(date, { month: "short", day: "numeric", year: "numeric", hour: "numeric", minute: "2-digit" })
    default:
      return formatRelativeTime(date, now)
  }
}

function formatRelativeTime(date, now) {
  const days = signedDifferenceInDays(now, date)

  if (days === 0) {
    return formatLocalTime(date, "time", now)
  } else if (days === -1) {
    return "yesterday"
  } else if (days < -1 && days > -7) {
    return `${Math.abs(days)} days ago`
  } else if (days === 1) {
    return "tomorrow"
  } else if (days > 1 && days < 7) {
    return `in ${days} days`
  } else {
    return formatLocalDate(date, now)
  }
}

function formatLocalDate(date, now) {
  const options = { month: "short", day: "numeric" }

  if (date.getFullYear() !== now.getFullYear()) options.year = "numeric"

  return formatDate(date, options)
}

function formatDate(date, options) {
  const key = JSON.stringify(options)

  if (!dateFormatterCache.has(key)) {
    dateFormatterCache.set(key, new Intl.DateTimeFormat("en-US", options))
  }

  return dateFormatterCache.get(key).format(date)
}
import { Controller } from "@hotwired/stimulus"
import { formatLocalTime } from "helpers/date_helpers"

export default class extends Controller {
  static values = { format: { type: String, default: "relative" } }

  connect() {
    this.#render()

    this.observer = new MutationObserver(() => this.#render())
    this.observer.observe(this.element, {
      attributes: true,
      attributeFilter: [ "datetime", "data-local-time-format-value" ],
      childList: true,
      characterData: true,
      subtree: true
    })
  }

  disconnect() {
    this.observer?.disconnect()
  }

  #render() {
    const timestamp = this.element.getAttribute("datetime")
    const date = new Date(timestamp)

    if (!timestamp || Number.isNaN(date.getTime())) return

    const text = formatLocalTime(date, this.formatValue)
    if (this.element.textContent !== text) this.element.textContent = text

    if (!this.element.hasAttribute("title")) {
      this.element.title = formatLocalTime(date, "date-time-with-year")
    }
  }
}
import { Controller } from "@hotwired/stimulus"

export default class extends Controller {
  static values = { userTimezone: String, updateUrl: String }

  connect() {
    const timezone = Intl.DateTimeFormat().resolvedOptions().timeZone

    this.#setTimezoneCookie(timezone)
    this.#updateUserTimezone(timezone)
  }

  #setTimezoneCookie(timezone) {
    document.cookie = `timezone=${encodeURIComponent(timezone)}; path=/`
  }

  #updateUserTimezone(timezone) {
    if (!this.userTimezoneValue || !this.updateUrlValue || this.userTimezoneValue === timezone) return

    const csrfToken = document.querySelector('meta[name="csrf-token"]')?.content

    fetch(this.updateUrlValue, {
      method: "PATCH",
      credentials: "same-origin",
      headers: {
        "Accept": "application/json",
        "Content-Type": "application/json",
        "X-CSRF-Token": csrfToken
      },
      body: JSON.stringify({ timezone_name: timezone })
    }).then(response => {
      if (response.ok) this.userTimezoneValue = timezone
    }).catch(error => {
      console.error("Unable to update timezone preference", error)
    })
  }
}
